# Homebrew formula for Kashif (vulnscan). Generated by packaging/update_formula.py at each release; do not edit.
#   brew tap kashif/vulnscan https://github.com/abdulrahmanahmedelabed-prog/vulnscan
#   brew install kashif
class Kashif < Formula
  desc "Zero-dependency SAST with inter-procedural dataflow analysis for 12 languages"
  homepage "https://abdulrahmanahmedelabed-prog.github.io/vulnscan/"
  version "0.9.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/abdulrahmanahmedelabed-prog/vulnscan/releases/download/v0.9.0/vulnscan-macos-arm64"
      sha256 "e2707965d0573081435c91a69d085a81cdfeb786dddc75f4e9a7b4e45867e7aa"
    end
    on_intel do
      url "https://github.com/abdulrahmanahmedelabed-prog/vulnscan/releases/download/v0.9.0/vulnscan-macos-x86_64"
      sha256 "38beff086a9ab8ddeffead784972307f651e5767b6e65ff54022a93f0b960133"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/abdulrahmanahmedelabed-prog/vulnscan/releases/download/v0.9.0/vulnscan-linux"
      sha256 "8f39a81d98f4d45d35772a58aafde67e624d296340475ee90e955811142d0ba6"
    end
  end

  def install
    binary = Dir["vulnscan-*"].first
    odie "release binary not found" if binary.nil?
    bin.install binary => "vulnscan"
    bin.install_symlink "vulnscan" => "kashif"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/vulnscan --version")
  end
end
